"""notes — a tiny note keeper (a list of strings in notes.json)."""
import json, os, sys

PATH = os.path.join(os.path.dirname(__file__), "notes.json")


def load():
    return json.load(open(PATH)) if os.path.exists(PATH) else []


def save(notes):
    json.dump(notes, open(PATH, "w"))


def add(text):
    notes = load()
    notes.append(text)
    save(notes)
    return len(notes)


def list_notes():
    return load()


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else "list"
    if cmd == "add":
        print(add(" ".join(sys.argv[2:])))
    else:
        for i, n in enumerate(list_notes(), 1):
            print(i, n)
